(function () {
  'use strict';
  const D=window.TourGuide, main=document.getElementById('conteudo'), key='mgtour.guia.v1';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const defaults=()=>({schema:'mgtour.guia/v1',context:{project:'Espaço Horizonte · estudo',platform:'3dvista',objective:'Apresentar três ambientes e facilitar a navegação.',brand:'Marca fictícia. Azul profundo, verde-lima e superfícies claras.'},checks:{},done:[]});
  function validate(raw){
    if(!raw||raw.schema!=='mgtour.guia/v1'||!raw.context||!['3dvista','pano2vr'].includes(raw.context.platform)||!Array.isArray(raw.done)||!raw.checks||typeof raw.checks!=='object'||Array.isArray(raw.checks))throw Error('Formato de progresso inválido.');
    const out=defaults();
    for(const field of ['project','objective','brand']){if(typeof raw.context[field]!=='string'||raw.context[field].length>1200)throw Error('Contexto inválido.');out.context[field]=raw.context[field];}
    out.context.platform=raw.context.platform;
    out.done=[...new Set(raw.done.filter(id=>D.lessons.some(l=>l.id===id)))];
    for(const l of D.lessons){const c=raw.checks[l.id];if(c!==undefined&&(!Array.isArray(c)||c.length!==l.checks.length||c.some(v=>typeof v!=='boolean')))throw Error('Lista de conferência inválida.');if(c)out.checks[l.id]=c.slice();}
    out.done=out.done.filter(id=>out.checks[id]?.every(Boolean));
    return out;
  }
  let state=defaults(),storageAvailable=true,noticeTimer;
  try{const raw=localStorage.getItem(key);if(raw)state=validate(JSON.parse(raw));}catch{storageAvailable=false;}
  function notify(text){const n=document.getElementById('notice');n.textContent=text;n.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.classList.remove('show'),5000);}
  function persist(){try{localStorage.setItem(key,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;notify('O navegador não salvou o rascunho. Exporte seu progresso para guardar.');}}
  const active=()=>D.activeLessons(state.context.platform);
  const progress=()=>active().filter(l=>state.done.includes(l.id)).length;
  function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  const allCommands=()=>D.commands.map(c=>D.commandText(c.id,state.context)).join('\n\n'+'─'.repeat(55)+'\n\n');
  function navRail(current){return `<aside class="rail"><h2>Seu caminho de criação</h2><p>Prepare. Experimente. Confira. Reutilize.</p><nav aria-label="Navegação do laboratório"><a href="#trilha" ${current==='trilha'?'aria-current="page"':''}>↗ Visão da trilha</a><a href="#biblioteca" ${current==='biblioteca'?'aria-current="page"':''}>✦ Biblioteca de comandos</a><a href="#materiais" ${current==='materiais'?'aria-current="page"':''}>▤ Materiais e progresso</a>${D.modules.map(([id,title])=>`<div class="rail-caption">${esc(title)}</div>${active().filter(l=>l.module===id).map(l=>`<a href="#aula/${l.id}" ${current===l.id?'aria-current="page"':''}><span class="rail-number">${state.done.includes(l.id)?'✓':String(active().indexOf(l)+1).padStart(2,'0')}</span>${esc(l.title)}</a>`).join('')}`).join('')}</nav><div class="rail-progress"><strong data-progress-label>${progress()} de ${active().length} etapas conferidas</strong><div class="progressbar"><span data-progress-bar style="width:${progress()/active().length*100}%"></span></div><p>Seu registro é local a este navegador. Exporte para levar com você.</p></div></aside>`;}
  function contextForm(){return `<details class="context"><summary>Contexto do projeto · ${esc(state.context.project||'Projeto de estudo')} · ${state.context.platform==='pano2vr'?'Pano2VR':'3DVista'} <span class="subtle">— editar</span></summary><form id="context-form"><label>Nome do projeto<input name="project" maxlength="1200" value="${esc(state.context.project)}"></label><label>Programa<select name="platform"><option value="3dvista" ${state.context.platform==='3dvista'?'selected':''}>3DVista</option><option value="pano2vr" ${state.context.platform==='pano2vr'?'selected':''}>Pano2VR</option></select></label><label class="full">Objetivo do visitante<textarea name="objective" rows="2" maxlength="1200">${esc(state.context.objective)}</textarea></label><label class="full">Identidade, materiais e decisões<textarea name="brand" rows="2" maxlength="1200">${esc(state.context.brand)}</textarea></label><div class="full actions"><button class="button dark" type="submit">Salvar contexto</button><p class="form-note">Os comandos usam estes dados. O rascunho fica neste navegador.</p></div></form></details>`;}
  function shell(current,body){return `<div class="lab-layout">${navRail(current)}<div class="lab-main"><div class="breadcrumb"><a href="#inicio">Café Expresso</a><span>/</span><a href="#trilha">Laboratório Tour 360</a></div>${body}</div></div>`;}
  function landing(){
    return `<div class="wrap"><section class="hero" aria-labelledby="hero-title"><div><div class="eyebrow">Método MG TOUR · Criação com IA</div><h1 id="hero-title">Sua identidade.<br>Seu panorama.<br><span>Seu próximo tour.</span></h1><p>Transforme uma ideia em uma skin personalizada. Um caminho guiado para criar, adaptar e conferir experiências em <strong>3DVista e Pano2VR.</strong></p><div class="actions"><a class="button primary" href="#trilha">Começar meu projeto <span aria-hidden="true">↗</span></a><a class="button" href="#biblioteca">Explorar os comandos <span aria-hidden="true">→</span></a></div><div class="hero-note"><span class="status-dot"></span>Laboratório de teste · Guias práticos · Vídeos ainda em produção</div></div><div class="visual-shell"><div class="visual-top"><span>ESPAÇO HORIZONTE <span class="subtle">/ ESTUDO DE SKIN</span></span><span class="dots" aria-hidden="true">● ● ●</span></div><div class="scene"><img src="cena.svg" alt="Ilustração de uma sala com sofá, janela ampla e interface de tour sobreposta." width="1000" height="700"><span class="scene-tag">EXPLORE CADA PERSPECTIVA</span><span class="hotspot" aria-hidden="true">↗</span><div class="scene-label"><small>01 / 03 AMBIENTES</small>Sala principal</div><div class="scene-menu" aria-hidden="true"><span>☰ Ambientes</span><span>◉ Informações</span><span>↗ Explorar</span><span>＋</span></div></div><div class="floating-note"><span class="check" aria-hidden="true">✓</span><div><strong>Pensada para cada tela</strong><span class="subtle">Desktop + mobile adaptativo</span></div></div><div class="visual-caption">ILUSTRAÇÃO AUTORAL · REPRESENTAÇÃO VISUAL, SEM PLAYER CONECTADO</div></div></section><div class="metrics"><div><strong>02</strong><span>Caminhos: 3DVista e Pano2VR</span></div><div><strong>06</strong><span>Módulos do método</span></div><div><strong>16</strong><span>Comandos para criar e revisar</span></div><div><strong>01</strong><span>Padrão próprio para reutilizar</span></div></div><section class="section"><div class="section-head"><div><div class="eyebrow">Uma experiência com a sua assinatura</div><h2>Crie com intenção.<br>Avance com clareza.</h2></div><p>A IA ajuda a executar. Sua direção dá personalidade, organiza a informação e mantém o visitante no centro.</p></div><div class="cards"><a class="card" href="#aula/briefing"><span class="number">01 / DIREÇÃO</span><h3>Da referência à sua identidade.</h3><p>Transforme cores, marca e objetivo em critérios claros. Componha uma experiência própria para cada projeto.</p><span class="arrow" aria-hidden="true">↗</span></a><a class="card" href="#aula/adaptativo"><span class="number">02 / EXPERIÊNCIA</span><h3>A mesma informação. Outra composição.</h3><p>Menu lateral no desktop, gaveta no celular. O conteúdo encontra a melhor forma de aparecer em cada tela.</p><span class="arrow" aria-hidden="true">↗</span></a><a class="card" href="#aula/entrega"><span class="number">03 / CONTINUIDADE</span><h3>Um projeto que abre o próximo.</h3><p>Guarde decisões, componentes e verificações. Reutilize o padrão preservando a identidade de cada cliente.</p><span class="arrow" aria-hidden="true">↗</span></a></div></section><section class="band"><div><div class="eyebrow">Do primeiro clique à entrega</div><h2>Bonita na tela.<br>Coerente na experiência.</h2><p>Comece por um pequeno percurso: abra o menu, escolha um ambiente, consulte uma informação e volte a explorar.</p><a class="button primary small" href="#aula/primeira-skin">Conhecer a primeira prática ↗</a></div><ul><li><span>01</span><div><strong>O panorama ganha espaço.</strong><br>Painéis e controles aparecem onde ajudam a navegação.</div></li><li><span>02</span><div><strong>O celular recebe atenção própria.</strong><br>Visibilidade, toque, orientação e retorno entram na composição.</div></li><li><span>03</span><div><strong>A integração precisa funcionar.</strong><br>Teste no programa escolhido e registre a evidência real.</div></li></ul></section><section class="section"><div class="section-head"><div><div class="eyebrow">Seu caminho no laboratório</div><h2>Uma etapa prepara a próxima.</h2></div><a class="text-link" href="#trilha">Ver a trilha completa →</a></div><div class="path-grid">${D.modules.map(([,title,desc],i)=>`<div class="path-item"><span>MÓDULO ${String(i+1).padStart(2,'0')}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`).join('')}</div></section><section class="cta-band"><div><div class="eyebrow">Café Expresso · Máquina de Tour 360</div><h2>A próxima experiência começa aqui.</h2><p>Escolha sua plataforma, organize o contexto e siga para a primeira entrega.</p></div><a class="button dark" href="#trilha">Entrar no laboratório ↗</a></section></div>`;
  }
  function lessonCards(items){return items.map(l=>`<a class="lesson-card" href="#aula/${l.id}"><div><small>${state.done.includes(l.id)?'✓ CONFERIDA':`${String(active().indexOf(l)+1).padStart(2,'0')} / GUIA PRÁTICO`}${l.platform!=='ambos'?' · '+(l.platform==='pano2vr'?'Pano2VR':'3DVista'):''}</small><h3>${esc(l.title)}</h3><p>${esc(l.result)}</p></div><span class="arrow" aria-hidden="true">↗</span></a>`).join('');}
  function trail(){return shell('trilha',`<div class="eyebrow">Guia do aluno · laboratório</div><h1>Seu tour. Um passo<br>de cada vez.</h1><p class="intro">Cada prática tem uma entrega, um comando e critérios para conferir. Escolha o programa e use um projeto de estudo antes de aplicar o método em um cliente.</p><div class="lesson-meta"><span class="pill">6 módulos</span><span class="pill">${active().length} guias no seu caminho</span><span class="pill green" data-progress-label>${progress()} de ${active().length} etapas conferidas</span></div>${contextForm()}<div class="notice">Este laboratório oferece orientação e comandos. A execução acontece no seu ambiente de trabalho. As aulas em vídeo e os projetos nativos de demonstração ainda estão em preparação.</div><div class="toolbar"><input type="search" id="lesson-search" aria-label="Buscar aula ou assunto" placeholder="Busque uma aula ou um assunto…"></div><div id="lesson-results">${modulesView('')}</div>`);}
  function modulesView(query){const q=query.toLocaleLowerCase('pt-BR');let count=0;const text=D.modules.map(([id,title,desc],i)=>{const items=active().filter(l=>l.module===id&&JSON.stringify(l).toLocaleLowerCase('pt-BR').includes(q));count+=items.length;return items.length?`<section class="module"><div class="module-head"><span>${String(i+1).padStart(2,'0')}</span><div><h2>${esc(title)}</h2><p>${esc(desc)}</p></div></div><div class="lesson-grid">${lessonCards(items)}</div></section>`:'';}).join('');return count?text:'<p class="empty" role="status">Nenhuma aula encontrada. Tente “mobile”, “painéis” ou “integração”.</p>';}
  function commandCard(id,open=false){const c=D.commands.find(c=>c.id===id);return `<section class="command"><div class="row"><div><small>${esc(c.category)}</small><h3>${esc(c.title)}</h3></div><button class="button small" data-copy="${c.id}">Copiar comando ↗</button></div><details ${open?'open':''}><summary>Ver e personalizar o pedido</summary><label for="cmd-${c.id}">Comando para seu projeto</label><textarea id="cmd-${c.id}" rows="9" spellcheck="false">${esc(D.commandText(c.id,state.context))}</textarea><div class="actions"><button class="button small" data-txt="${c.id}">Baixar TXT</button><small>Texto editável. Execute no agente que tem acesso ao seu projeto.</small></div></details></section>`;}
  function library(){return shell('biblioteca',`<div class="eyebrow">Biblioteca de comandos</div><h1>O pedido certo.<br>No momento certo.</h1><p class="intro">16 comandos próprios para orientar criação, adaptação, integração e revisão. Use apenas o que seu projeto precisa.</p>${contextForm()}<div class="toolbar"><input id="command-search" type="search" aria-label="Buscar comando" placeholder="Buscar por função ou problema…"><select id="command-category" aria-label="Filtrar comandos por categoria"><option value="">Todas as categorias</option>${[...new Set(D.commands.map(c=>c.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><button class="button dark" data-download="comandos">Baixar todos · TXT</button></div><p id="command-count" class="subtle" role="status">16 comandos disponíveis</p><div id="command-results">${D.commands.map(c=>commandCard(c.id)).join('')}</div>`);}
  function lessonPage(id){const l=D.lessons.find(l=>l.id===id);if(!l)return shell('',`<h1>Guia não encontrado.</h1><a class="button dark" href="#trilha">Voltar à trilha</a>`);if(l.platform!=='ambos'&&l.platform!==state.context.platform)return shell('',`<h1>Escolha o caminho ${l.platform==='pano2vr'?'Pano2VR':'3DVista'}.</h1><p class="intro">Este guia pertence a outra plataforma. Troque o programa no contexto para trabalhar com seus arquivos e ações.</p>${contextForm()}<a class="button" href="#trilha">Voltar à trilha</a>`);const list=active(),index=list.indexOf(l),checks=state.checks[l.id]||l.checks.map(()=>false),done=state.done.includes(l.id);return shell(l.id,`<div class="eyebrow">${String(index+1).padStart(2,'0')} / ${esc(D.modules.find(m=>m[0]===l.module)[1])}</div><h1>${esc(l.title)}</h1><p class="intro">${esc(l.result)}</p><div class="lesson-meta"><span class="pill">${l.steps.length} passos</span><span class="pill">${l.commands.length} comando${l.commands.length>1?'s':''}</span><span class="pill">${l.platform==='ambos'?'Base comum':l.platform==='pano2vr'?'Pano2VR':'3DVista'}</span></div>${contextForm()}<div class="steps">${l.steps.map(([title,text],i)=>`<section class="step"><span class="step-number">${i+1}</span><div><h2>${esc(title)}</h2><p>${esc(text)}</p></div></section>`).join('')}</div><h2 class="section-title">Comandos para esta prática</h2>${l.commands.map(id=>commandCard(id,l.commands.length===1)).join('')}<section class="checklist"><h2>Confira antes de avançar</h2><p class="subtle">Marque o que você realmente conferiu no seu trabalho.</p>${l.checks.map((c,i)=>`<label><input type="checkbox" data-check="${l.id}" data-index="${i}" ${checks[i]?'checked':''}><span>${esc(c)}</span></label>`).join('')}<button id="complete-lesson" class="button dark" data-complete="${l.id}" ${!done&&!checks.every(Boolean)?'disabled':''}>${done?'Etapa conferida · desfazer':'Registrar etapa como conferida'}</button><p style="font-size:11px;margin:14px 0 0">Registro pessoal de progresso. Não certifica testes ou compatibilidade do tour.</p></section><nav class="lesson-nav" aria-label="Sequência das práticas"><a href="${index?'#aula/'+list[index-1].id:'#trilha'}"><small>← Anterior</small>${index?esc(list[index-1].title):'Visão da trilha'}</a><a class="next" href="${list[index+1]?'#aula/'+list[index+1].id:'#materiais'}"><small>Próxima →</small>${list[index+1]?esc(list[index+1].title):'Materiais e continuidade'}</a></nav>`);}
  const resources=[['comandos','TXT','Todos os comandos','16 pedidos com o contexto do seu projeto.'],['briefing','JSON','Ficha de briefing','Objetivo, programa e identidade do projeto.'],['pastas','TXT','Estrutura do trabalho','Pastas sugeridas e regras de preservação.'],['adaptacao','CSV','Equivalência desktop/mobile','Função, acesso, abertura, fechamento e retorno.'],['testes','CSV','Matriz de testes','Ambiente, versão, passos e evidência.'],['revisao','CSV','Ficha de revisão','Defeito, causa, correção e resultado observado.'],['custos','CSV','Registro de esforço e custos','Tempo ativo, espera e valores confirmados.'],['variacoes','CSV','Matriz de variações','Base, variável, hipótese e comparação.']];
  function materials(){return shell('materiais',`<div class="eyebrow">Materiais e continuidade</div><h1>Seu método.<br>Sempre à mão.</h1><p class="intro">Arquivos próprios para praticar, conferir e retomar. Os exemplos usam o projeto fictício Espaço Horizonte.</p>${contextForm()}<div class="resources">${resources.map(([id,type,title,text])=>`<button class="resource" data-download="${id}"><span class="filetype">${type} ↓</span><span><strong>${title}</strong><p>${text}</p></span></button>`).join('')}</div><h2 class="section-title">Leve seu progresso com você.</h2><p class="intro">O contexto e as conferências ficam neste navegador. Não há sincronização entre aparelhos ou armazenamento em uma conta.</p>${!storageAvailable?'<div class="notice">O armazenamento local está indisponível. Exporte antes de fechar.</div>':''}<div class="actions"><button class="button dark" id="export-state">Exportar progresso · JSON</button><a class="button" href="#imprimir">Imprimir / salvar guia em PDF</a></div><details class="context"><summary>Importar um progresso salvo</summary><div style="padding:0 22px 22px"><label for="import-state">Arquivo JSON exportado por este guia</label><input class="file-input" id="import-state" type="file" accept=".json,application/json"><p class="subtle" style="font-size:12px;margin-top:12px">A importação substitui o rascunho deste navegador. Exporte o atual primeiro. Arquivos acima de 1 MB não são aceitos.</p><button class="button" id="apply-import">Importar arquivo selecionado</button></div></details><h2 class="section-title">Documentação dos fabricantes</h2><div class="resources"><a class="resource" href="https://www.3dvista.com/en/kb/" target="_blank" rel="noopener noreferrer"><span class="filetype">↗</span><span><strong>3DVista · Base de conhecimento</strong><p>Consulte ações, exportação e recursos compatíveis com sua versão.</p></span></a><a class="resource" href="https://ggnome.com/doc/pano2vr/" target="_blank" rel="noopener noreferrer"><span class="filetype">↗</span><span><strong>Pano2VR · Documentação</strong><p>Consulte nós, skins, componentes e configurações de saída.</p></span></a></div><div class="notice">Os arquivos deste guia organizam o trabalho. Não incluem software, licença, modelos de IA, projetos nativos prontos ou integração automática. Safari/iPhone e os players precisam de verificação real.</div>`);}
  function printable(){return shell('',`<div class="print-guide"><div class="eyebrow">MG TOUR · Guia de prática</div><h1>Máquina de Tour 360</h1><p>${esc(state.context.project)} · ${state.context.platform==='pano2vr'?'Pano2VR':'3DVista'}</p><p>Protótipo didático. As instruções precisam ser aplicadas e verificadas no projeto real. Progresso pessoal não certifica integração.</p><div class="actions no-print"><button class="button dark" id="print">Imprimir / salvar em PDF</button><a class="button" href="#materiais">Voltar aos materiais</a></div>${active().map(l=>`<article><h2>${esc(l.title)}</h2><p>${esc(l.result)}</p>${l.steps.map(([title,text])=>`<section class="step"><div><h3>${esc(title)}</h3><p>${esc(text)}</p></div></section>`).join('')}<p><strong>Confira:</strong> ${l.checks.map(esc).join(' · ')}</p>${l.commands.map(id=>`<pre>${esc(D.commandText(id,state.context))}</pre>`).join('')}</article>`).join('')}</div>`);}
  function material(id){let text='',name=id+'.csv',type='text/csv;charset=utf-8';const header=s=>'\uFEFF'+s+'\r\n';
    if(id==='comandos')return download('comandos-tour360.txt',allCommands());
    if(id==='briefing')return download('briefing-tour360.json',JSON.stringify({schema:'mgtour.briefing/v1',...state.context,ambientes:[],destinos:[],pendencias:[]},null,2),'application/json');
    if(id==='pastas')return download('estrutura-tour360.txt','MEU-TOUR/\n  originais/      Projeto nativo e mídias preservadas\n  assets/         Materiais autorizados\n  trabalho/       Cópia editável\n  saidas/         Exportações por versão\n  evidencias/     Capturas, passos e resultados\n  documentos/     Briefing, padrão e retomada\n\nAdapte aos caminhos reais do programa. Não mova mídias referenciadas sem conferir dependências. Mantenha as versões anteriores. Não envie dados ou mídias de clientes a um repositório público.');
    if(id==='adaptacao')text=header('funcao,desktop,mobile,acesso,abertura,fechamento,retorno,estado')+'"Ambientes","Painel lateral","Gaveta","Botão Ambientes","Por verificar","Por verificar","Preservar ambiente e seleção","planejado"\r\n"Informações","Janela","Painel","Botão Informações","Por verificar","Por verificar","Retornar ao controle de origem","planejado"';
    if(id==='testes')text=header('ambiente,dispositivo,versao,dimensoes,orientacao,passos,esperado,observado,evidencia,estado')+['Desktop','Emulação Chromium','Safari iPhone iOS 18 físico','Safari iPhone versão atual físico','Android físico'].map(x=>`"${x}","","","","","Abrir menu; trocar ambiente; abrir e fechar painel","Navegação e retorno preservados","","","pendente"`).join('\r\n');
    if(id==='revisao')text=header('versao,componente,ambiente,passos,esperado,observado,causa,correcao,preservar,evidencia,estado');
    if(id==='custos')text=header('data,projeto,versao,tempo_ativo_min,espera_min,assinatura_alocada,licenca_alocada,api,extras,hospedagem,moeda,entregas_aprovadas,fonte_dos_valores');
    if(id==='variacoes')text=header('versao,base,variavel_alterada,hipotese,percurso,resultado_observado,evidencia')+'"A-base","","nenhuma","Referência de comparação","Mesmo percurso","",""\r\n"B-variacao","A-base","preencher","preencher","Mesmo percurso","",""';
    if(text)download('tour360-'+name,text,type);
  }
  function updateProgress(){for(const el of document.querySelectorAll('[data-progress-label]'))el.textContent=`${progress()} de ${active().length} etapas conferidas`;for(const el of document.querySelectorAll('[data-progress-bar]'))el.style.width=progress()/active().length*100+'%';}
  function wire(){
    document.getElementById('context-form')?.addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.currentTarget);for(const f of ['project','platform','objective','brand'])state.context[f]=String(form.get(f)||'').trim();persist();render(false);notify('Contexto salvo. Os comandos já usam suas decisões.');});
    document.getElementById('lesson-search')?.addEventListener('input',e=>document.getElementById('lesson-results').innerHTML=modulesView(e.target.value));
    const filter=()=>{const q=document.getElementById('command-search').value.toLocaleLowerCase('pt-BR'),cat=document.getElementById('command-category').value;const list=D.commands.filter(c=>(!cat||c.category===cat)&&(c.title+' '+c.prompt).toLocaleLowerCase('pt-BR').includes(q));document.getElementById('command-results').innerHTML=list.length?list.map(c=>commandCard(c.id)).join(''):'<p class="empty">Nenhum comando encontrado. Tente outro assunto.</p>';document.getElementById('command-count').textContent=`${list.length} ${list.length===1?'comando disponível':'comandos disponíveis'}`;};
    document.getElementById('command-search')?.addEventListener('input',filter);document.getElementById('command-category')?.addEventListener('change',filter);
    document.getElementById('export-state')?.addEventListener('click',()=>download('progresso-tour360.json',JSON.stringify(state,null,2),'application/json'));
    document.getElementById('print')?.addEventListener('click',()=>window.print());
    document.getElementById('apply-import')?.addEventListener('click',async()=>{const file=document.getElementById('import-state').files[0];if(!file)return notify('Selecione o arquivo de progresso.');if(file.size>1024*1024)return notify('Arquivo maior que o limite de 1 MB.');try{const incoming=validate(JSON.parse(await file.text()));state=incoming;persist();render(false);notify('Progresso importado.');}catch{notify('Arquivo inválido. O progresso atual foi preservado.');}});
  }
  main.addEventListener('change',e=>{const el=e.target;if(!el.matches('[data-check]'))return;const l=D.lessons.find(l=>l.id===el.dataset.check);if(!l)return;const values=state.checks[l.id]||l.checks.map(()=>false);values[Number(el.dataset.index)]=el.checked;state.checks[l.id]=values;if(!values.every(Boolean))state.done=state.done.filter(id=>id!==l.id);persist();const b=document.getElementById('complete-lesson');b.disabled=!values.every(Boolean);b.textContent=state.done.includes(l.id)?'Etapa conferida · desfazer':'Registrar etapa como conferida';updateProgress();});
  main.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
    if(b.dataset.copy){const area=document.getElementById('cmd-'+b.dataset.copy),text=area?.value||D.commandText(b.dataset.copy,state.context);try{await navigator.clipboard.writeText(text);notify('Comando copiado. Cole no agente do seu projeto.');}catch{area.closest('details').open=true;area.focus();area.select();notify('Selecionei o texto. Use copiar no seu dispositivo.');}}
    if(b.dataset.txt){const area=document.getElementById('cmd-'+b.dataset.txt);download('tour360-'+b.dataset.txt+'.txt',area?.value||D.commandText(b.dataset.txt,state.context));}
    if(b.dataset.download)material(b.dataset.download);
    if(b.dataset.complete){const id=b.dataset.complete;if(state.done.includes(id))state.done=state.done.filter(x=>x!==id);else if(state.checks[id]?.every(Boolean))state.done.push(id);else return;persist();b.textContent=state.done.includes(id)?'Etapa conferida · desfazer':'Registrar etapa como conferida';updateProgress();notify(state.done.includes(id)?'Etapa registrada no seu progresso.':'Registro da etapa desfeito.');}
  });
  const menu=document.getElementById('mobile-menu'),trigger=document.getElementById('open-menu');
  trigger.addEventListener('click',()=>{menu.showModal();trigger.setAttribute('aria-expanded','true');});
  document.getElementById('close-menu').addEventListener('click',()=>menu.close());
  menu.addEventListener('close',()=>{trigger.setAttribute('aria-expanded','false');trigger.focus();});
  menu.addEventListener('click',e=>{if(e.target.closest('a'))menu.close();if(e.target===menu){const r=menu.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)menu.close();}});
  function render(move=true){
    const route=location.hash.slice(1)||'inicio';const title=route.startsWith('aula/')?D.lessons.find(l=>l.id===route.slice(5))?.title:({inicio:'Máquina de Tour 360',trilha:'Guia do aluno',biblioteca:'Biblioteca de comandos',materiais:'Materiais e progresso',imprimir:'Guia para impressão'}[route]);
    document.title=(title||'Máquina de Tour 360')+' · Café Expresso';
    main.innerHTML=route==='inicio'?landing():route==='trilha'?trail():route==='biblioteca'?library():route==='materiais'?materials():route==='imprimir'?printable():route.startsWith('aula/')?lessonPage(route.slice(5)):shell('',`<h1>Página não encontrada.</h1><a class="button dark" href="#trilha">Voltar ao guia</a>`);
    for(const a of document.querySelectorAll('.desktop-nav a')){a.removeAttribute('aria-current');if(a.getAttribute('href')==='#'+route)a.setAttribute('aria-current','page');}
    wire();if(move){window.scrollTo(0,0);main.focus({preventScroll:true});}
  }
  document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
  window.addEventListener('hashchange',()=>render());render(false);
})();
